INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Auswahlkriterien IT-Produkte > Qualität & Leistungsfähigkeit
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Qualität und Leistungsfähigkeit bei der Auswahl von IT-Produkten immer berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sichern Funktionalität und Zuverlässigkeit"}, {"text": "Nein", "correct": false, "because": "Kernkriterien"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Produkte ohne Rücksicht auf die Qualität langfristig effizient sein?', 2, '[{"text": "Nein", "correct": true, "because": "Minderwertige Qualität führt zu Ausfällen"}, {"text": "Ja", "correct": false, "because": "Qualität ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Leistungsfähigkeit eines IT-Produkts unabhängig von den Anforderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Muss Anforderungen entsprechen"}, {"text": "Ja", "correct": false, "because": "Anforderungen bestimmen Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Qualitätsstandards bei der Auswahl von IT-Produkten ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Standards sichern Zuverlässigkeit"}, {"text": "Ja", "correct": false, "because": "Standards sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Qualität und Leistungsfähigkeit nur bei teuren IT-Produkten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Preisklassen"}, {"text": "Ja", "correct": false, "because": "Universell wichtig"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Qualität von IT-Produkten am wichtigsten?', 3, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Sichert dauerhafte Funktion"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor definiert die Leistungsfähigkeit eines IT-Produkts?', 2, '[{"text": "Verarbeitungsgeschwindigkeit", "correct": true, "because": "Misst Effizienz"}, {"text": "Design", "correct": false, "because": "Ästhetisch"}, {"text": "Marke", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird oft zur Beurteilung der Qualität herangezogen?', 2, '[{"text": "Fehlerquote", "correct": true, "because": "Zeigt Zuverlässigkeit"}, {"text": "Gewicht", "correct": false, "because": "Physisch"}, {"text": "Preis", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, die Leistungsfähigkeit von IT-Produkten zu bewerten?', 3, '[{"text": "Benchmarks", "correct": true, "because": "Vergleichbare Leistungstests"}, {"text": "Farbtests", "correct": false, "because": "Ästhetisch"}, {"text": "Kostenanalyse", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil hoher Qualität bei IT-Produkten?', 2, '[{"text": "Langlebigkeit", "correct": true, "because": "Verlängert Nutzungsdauer"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht immer"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Qualität von IT-Produkten?', 4, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Sichert Funktion"}, {"text": "Verarbeitung", "correct": true, "because": "Materialqualität"}, {"text": "Fehlerquote", "correct": true, "because": "Misst Ausfälle"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien bestimmen die Leistungsfähigkeit von IT-Produkten?', 3, '[{"text": "Prozessorleistung", "correct": true, "because": "Geschwindigkeit"}, {"text": "Speicherkapazität", "correct": true, "because": "Datenverarbeitung"}, {"text": "Bandbreite", "correct": true, "because": "Netzwerkgeschwindigkeit"}, {"text": "Gewicht", "correct": false, "because": "Physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet hohe Qualität bei IT-Produkten?', 3, '[{"text": "Geringere Ausfallzeiten", "correct": true, "because": "Zuverlässigkeit"}, {"text": "Längere Lebensdauer", "correct": true, "because": "Dauerhafte Nutzung"}, {"text": "Hohe Benutzerzufriedenheit", "correct": true, "because": "Bessere Erfahrung"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei mangelnder Qualität von IT-Produkten auftreten?', 4, '[{"text": "Häufige Ausfälle", "correct": true, "because": "Fehlende Zuverlässigkeit"}, {"text": "Hohe Wartungskosten", "correct": true, "because": "Reparaturen nötig"}, {"text": "Geringe Leistung", "correct": true, "because": "Eingeschränkte Funktion"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, Qualität und Leistungsfähigkeit zu bewerten?', 3, '[{"text": "Benchmarks", "correct": true, "because": "Leistungstest"}, {"text": "Zertifizierungen", "correct": true, "because": "Qualitätsnachweis"}, {"text": "Nutzerbewertungen", "correct": true, "because": "Erfahrungen"}, {"text": "Farbtests", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Qualität beeinflusst die Langlebigkeit von IT-Produkten. b) Leistungsfähigkeit ist unabhängig von Anforderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, Leistung abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Benchmarks bewerten die Leistungsfähigkeit von IT-Produkten. b) Qualität ist bei günstigen Produkten irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Benchmarks ja, Qualität immer wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zuverlässigkeit ist ein Qualitätskriterium bei IT-Produkten. b) Standards können bei der Auswahl ignoriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zuverlässigkeit ja, Standards wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Hohe Qualität reduziert Wartungskosten. b) Leistungsfähigkeit ist nur bei teuren Produkten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, Leistung allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlerquote ist ein Indikator für Qualität. b) Qualität und Leistungsfähigkeit sind bei der Auswahl unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlerquote ja, Kriterien wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

